{
    if (!skb || skb->len <= dev->mtu)
        return skb;

    if (skb->protocol != htons(ETH_P_IPV6))
        return ERR_PTR(-EINVAL);

    struct iphdr *ipv6_hdr = ipv6_hdr(skb);
    struct udphdr *udp_hdr = udp_hdr(skb);

    if (ipv6_hdr->nexthdr != IPPROTO_UDP)
        return ERR_PTR(-EINVAL);

    if (!udp_hdr || ntohs(udp_hdr->len) <= dev->mtu)
        return skb;

    if (skb_checksum_help(skb))
        return ERR_PTR(-EINVAL);

    skb = skb_share_check(skb, GFP_ATOMIC);
    if (!skb)
        return ERR_PTR(-ENOMEM);

    skb = skb_segment(skb, features);
    if (IS_ERR(skb))
        return skb;

    return skb;
}

struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features)
{
    if (!skb || skb->len <= MSS)
        return ERR_PTR(-EINVAL);

    if (skb->protocol != htons(ETH_P_IPV6))
        return ERR_PTR(-EPROTO);

    skb_checksum_help(skb);
    skb_push(skb, sizeof(struct ipv6hdr));
    skb_reset_transport_header(skb);

    struct ipv6hdr *ipv6h = ipv6_hdr(skb);
    if (ipv6h->nexthdr != NEXTHDR_UDP)
        return ERR_PTR(-EPROTO);

    skb = skb_segment(skb, features);
    if (IS_ERR(skb))
        return skb;

    struct sk_buff *iter;
    for (iter = skb; iter; iter = iter->next) {
        ipv6h = ipv6_hdr(iter);
        ipv6h->payload_len = htons(iter->len - sizeof(struct ipv6hdr));
        if (iter->next)
            ipv6h->frag_off |= htons(IP6_MF);
    }

    return skb;
}

struct sk_buff *fragment_udp_ipv6_packet(struct sk_buff *skb, u32 features)
{
    int mss = 1280; // default minimum IPv6 MTU
    int payload_len = skb->len;

    if (payload_len <= mss)
        return skb;

    if (!skb_is_gso(skb)) {
        return ERR_PTR(-EINVAL);
    }

    skb->csum = 0;
    skb->ip_summed = CHECKSUM_NONE;

    skb_push(skb, sizeof(struct udphdr));
    skb_reset_transport_header(skb);

    struct udphdr *uh = udp_hdr(skb);
    uh->check = 0;
    uh->check = csum_tcpudp_nofold(skb->nh.iph->saddr, skb->nh.iph->daddr, payload_len, IPPROTO_UDP, skb->csum);

    skb_pop(skb, sizeof(struct udphdr));

    struct sk_buff *segments = skb_gso_segment(skb, features);

    if (IS_ERR(segments))
        return segments;

    struct sk_buff *frag;
    skb_queue_walk(segments, frag) {
        skb_push(frag, sizeof(struct udphdr));
        skb_reset_transport_header(frag);

        struct udphdr *frag_uh = udp_hdr(frag);
        frag_uh->check = 0;
        frag_uh->check = csum_tcpudp_nofold(skb->nh.iph->saddr, skb->nh.iph->daddr, frag->len, IPPROTO_UDP, 0);
    }

    return segments;
}

struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features) {
    int mss = skb_mtu(skb);
    int payload_len = skb->len;

    if (payload_len <= mss)
        return skb;

    if (!skb_is_gso(skb)) {
        skb = skb_share_check(skb, GFP_ATOMIC);
        if (!skb)
            return ERR_PTR(-ENOMEM);
    }

    skb_checksum_help(skb);

    skb = ip6_fragment(skb, features);
    if (IS_ERR(skb))
        return skb;

    return skb;
}

struct sk_buff *fragment_udp_packet(struct sk_buff *skb, u32 features)
{
    int mss = skb->dev ? skb->dev->mtu - sizeof(struct ipv6hdr) - sizeof(struct udphdr) : 0;

    if (skb->len <= mss)
        return skb;

    if (!skb_is_gso(skb)) {
        return ERR_PTR(-EINVAL);
    }

    skb_checksum_help(skb);

    skb_push(skb, sizeof(struct udphdr));
    skb_pull(skb, sizeof(struct udphdr));

    skb = skb_gso_segment(skb, features);
    if (IS_ERR(skb))
        return skb;

    return skb;
}
